#include <assert.h>
#include <stdio.h>
#include <string.h>
#include "wf_r17_post7a00.h"

typedef struct call9 {uint16_t d2,d7;uint32_t dest;} call9_t;
typedef struct sink {call9_t a[8];unsigned na;wf_r17_fg0_write_t fg[64];size_t nfg;uint32_t peek_value,peek_addr;unsigned npeek;} sink_t;
static wf_status_t raw9(wf_runtime_t*rt,uint16_t d2,uint16_t d7,uint32_t dest,void*u){sink_t*s=(sink_t*)u;unsigned i;assert(s->na<8u);s->a[s->na++]=(call9_t){d2,d7,dest};for(i=0;i<8u;i++)rt->m68k_regs.d[i]=0xdead0000u+i;return WF_OK;}
static wf_status_t fg(wf_runtime_t*rt,const wf_r17_fg0_write_t*w,size_t n,void*u){sink_t*s=(sink_t*)u;(void)rt;assert(n<=64u);memcpy(s->fg,w,n*sizeof(*w));s->nfg=n;return WF_OK;}
static wf_status_t peek(wf_runtime_t*rt,uint32_t addr,uint32_t*v,void*u){sink_t*s=(sink_t*)u;(void)rt;s->npeek++;s->peek_addr=addr;*v=s->peek_value;return WF_OK;}
static void init(wf_runtime_t*r,wf_r17_post7_ctx_t*c,sink_t*s){memset(r,0,sizeof(*r));memset(c,0,sizeof(*c));memset(s,0,sizeof(*s));r->m68k_regs.valid=1u;r->g.credited_route=1u;c->raw_9aca=raw9;c->fg0_batch=fg;c->fg0_peek_long=peek;c->user=s;r->m68k_regs.d[0]=0xaaaa1111u;r->m68k_regs.d[1]=0xbbbb2222u;r->m68k_regs.d[2]=0xcccc3333u;r->m68k_regs.d[3]=0xdddd4444u;r->m68k_regs.d[7]=0x77778888u;}
static void active(wf_actor_raw_t*a){wf_set_u8(a,WF_A_ACTIVE,0x80u);}
static void test_gate(void){wf_runtime_t r,b;wf_r17_post7_ctx_t c;sink_t s;init(&r,&c,&s);r.g.global_16c4=1u;b=r;assert(wf_r17_owner_c710(&r,&c)==WF_OK);assert(memcmp(&r,&b,sizeof(r))==0);assert(s.na==0u&&s.npeek==0u);puts("PASS $C710 main gate");}
static void test_wrap_ce_skip(void){wf_runtime_t r;wf_r17_post7_ctx_t c;sink_t s;init(&r,&c,&s);r.g.global_16ce=4u;wf_set_u8(&r.actors[0],0xceu,0x80u);assert(wf_r17_owner_c710(&r,&c)==WF_OK);assert(r.g.global_16ce==1u);assert(s.na==0u);puts("PASS $C710 index wrap + CE skip");}
static void test_cb42_clear(void){wf_runtime_t r;wf_r17_post7_ctx_t c;sink_t s;init(&r,&c,&s);r.g.progression_0162=4u;s.peek_value=0x12345678u;assert(wf_r17_owner_c710(&r,&c)==WF_OK);assert(s.npeek==1u&&s.peek_addr==0x000c0110u);assert(s.nfg==36u);assert(s.fg[0].addr==0x000c0104u&&s.fg[0].width==4u&&s.fg[0].value==0u);assert(s.fg[35].addr==0x000c0424u);assert(r.g.global_16ce==1u);assert(r.m68k_regs.d[2]==0x0000ffffu&&r.m68k_regs.d[3]==0x0000ffffu);puts("PASS $C710 $CB42 exact TST.L + 4x9 clear");}
static void test_inactive_no_credit(void){wf_runtime_t r;wf_r17_post7_ctx_t c;sink_t s;init(&r,&c,&s);assert(wf_r17_owner_c710(&r,&c)==WF_OK);assert(r.g.global_16ce==1u);assert(wf_u8(&r.actors[0],0xc2u)==0x18u&&wf_u8(&r.actors[0],0xc3u)==0x19u);assert(s.na==2u);assert(s.a[0].d2==0x18u&&s.a[0].d7==0x10u&&s.a[0].dest==0x000c0104u);assert(s.a[1].d2==0x19u&&s.a[1].dest==0x000c0308u);puts("PASS $C710 inactive no-credit selectors 18/19");}
static void test_active_no_credit(void){wf_runtime_t r;wf_r17_post7_ctx_t c;sink_t s;init(&r,&c,&s);active(&r.actors[0]);assert(wf_r17_owner_c710(&r,&c)==WF_OK);assert(wf_u8(&r.actors[0],0xc2u)==0x20u&&wf_u8(&r.actors[0],0xc3u)==0x21u);assert(s.na==2u&&s.a[0].d2==0x20u&&s.a[0].dest==0x000c0110u&&s.a[1].d2==0x21u&&s.a[1].dest==0x000c0210u);puts("PASS $C710 active no-credit selectors 20/21");}
static void test_active_code2(void){wf_runtime_t r;wf_r17_post7_ctx_t c;sink_t s;init(&r,&c,&s);active(&r.actors[0]);wf_set_u8(&r.actors[0],WF_A_FLAGS33,0x02u);assert(wf_r17_owner_c710(&r,&c)==WF_OK);assert(wf_u8(&r.actors[0],0xc2u)==0x20u&&wf_u8(&r.actors[0],0xc3u)==0x26u);assert(s.na==2u&&s.a[1].d2==0x26u&&s.a[1].dest==0x000c0210u);puts("PASS $C710 active code2 selectors 20/26");}
static void test_active_credit_c892_remap(void){wf_runtime_t r;wf_r17_post7_ctx_t c;sink_t s;init(&r,&c,&s);active(&r.actors[0]);r.g.credit_count_004f=1u;wf_set_be32(&r.actors[0],WF_A_INPUT_SOURCE,0x00140020u);assert(wf_r17_owner_c710(&r,&c)==WF_OK);assert(wf_u8(&r.actors[0],0xc2u)==0x23u&&wf_u8(&r.actors[0],0xc3u)==0x21u);assert(s.na==2u&&s.a[0].d2==0x23u&&s.a[0].dest==0x000c0110u);puts("PASS $C710 $C892 control-map selector");}
static void test_peek_zero_no_clear(void){wf_runtime_t r;wf_r17_post7_ctx_t c;sink_t s;init(&r,&c,&s);r.g.progression_0162=9u;s.peek_value=0u;assert(wf_r17_owner_c710(&r,&c)==WF_OK);assert(s.npeek==1u&&s.nfg==0u&&r.g.global_16ce==1u);puts("PASS $C710 $CB42 zero fast-return");}
static void test_missing_peek_rollback(void){wf_runtime_t r,b;wf_r17_post7_ctx_t c;sink_t s;init(&r,&c,&s);r.g.progression_0162=4u;c.fg0_peek_long=0;b=r;assert(wf_r17_owner_c710(&r,&c)==WF_BLOCKED);assert(c.blocked_dependency_rom==0x000c0110u);assert(memcmp(&r.m68k_regs,&b.m68k_regs,sizeof(r.m68k_regs))==0);assert(r.g.global_16ce==b.g.global_16ce);assert(memcmp(r.actors,b.actors,4u*sizeof(r.actors[0]))==0);assert(s.nfg==0u&&s.na==0u);puts("PASS $C710 fail-closed FG0 peek dependency");}
int main(void){test_gate();test_wrap_ce_skip();test_cb42_clear();test_inactive_no_credit();test_active_no_credit();test_active_code2();test_active_credit_c892_remap();test_peek_zero_no_clear();test_missing_peek_rollback();return 0;}
